import React, { useState, useEffect, useCallback } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import Sidebar from './Sidebar';
import { logout } from '../../store/authSlice';

const DashboardLayout = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const user = useSelector((state) => state.auth.user);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);

  // Обработка изменения размера окна
  useEffect(() => {
    const handleResize = () => {
      setWindowWidth(window.innerWidth);
      if (window.innerWidth > 768 && isMobileMenuOpen) {
        setIsMobileMenuOpen(false);
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isMobileMenuOpen]);

  // Закрытие мобильного меню при смене маршрута
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location.pathname]);

  const handleLogout = useCallback(async () => {
    try {
      // Показываем подтверждение перед выходом
      const confirmLogout = window.confirm('Вы уверены, что хотите выйти из системы?');
      if (!confirmLogout) return;

      // Опционально: вызвать API для выхода на сервере
      // await api.post('/auth/logout/');
      
      // Очищаем Redux состояние
      dispatch(logout());
      
      // Очищаем локальное хранилище если нужно
      localStorage.removeItem('token');
      sessionStorage.removeItem('token');
      
      // Показываем уведомление
      toast.success('Вы успешно вышли из системы');
      
      // Перенаправляем на страницу входа
      navigate('/login', { replace: true });
    } catch (error) {
      console.error('Ошибка при выходе:', error);
      toast.error('Ошибка при выходе из системы');
    }
  }, [dispatch, navigate]);

  // Форматирование времени и даты для шапки
  const [currentDateTime, setCurrentDateTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentDateTime(new Date());
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const formattedDate = currentDateTime.toLocaleDateString('ru-RU', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const formattedTime = currentDateTime.toLocaleTimeString('ru-RU', {
    hour: '2-digit',
    minute: '2-digit'
  });

  // Функция для переключения мобильного меню
  const toggleMobileMenu = useCallback(() => {
    setIsMobileMenuOpen(prev => !prev);
  }, []);

  // Определение заголовка страницы на основе текущего пути
  const getPageTitle = useCallback(() => {
    const path = location.pathname;
    switch (path) {
      case '/':
        return 'Главная панель';
      case '/schedule':
        return 'Расписание смен';
      case '/time-tracking':
        return 'Учёт рабочего времени';
      case '/employees':
        return 'Управление сотрудниками';
      case '/reports':
        return 'Отчёты и аналитика';
      default:
        return 'Система учёта рабочего времени';
    }
  }, [location.pathname]);

  const isMobile = windowWidth < 768;

  return (
    <div style={{ 
      display: 'flex', 
      minHeight: '100vh', 
      background: '#f1f5f9',
      position: 'relative',
    }}>
      
      {/* Оверлей для мобильного меню */}
      {isMobile && isMobileMenuOpen && (
        <div
          onClick={toggleMobileMenu}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            zIndex: 999,
            transition: 'all 0.3s ease',
          }}
          aria-label="Закрыть меню"
        />
      )}

      {/* Сайдбар с адаптивной шириной */}
      <div style={{
        position: isMobile ? 'fixed' : 'relative',
        left: isMobile && !isMobileMenuOpen ? -260 : 0,
        transition: 'left 0.3s ease',
        zIndex: 1000,
      }}>
        <Sidebar isMobile={isMobile} onClose={toggleMobileMenu} />
      </div>

      {/* Основной контент */}
      <div style={{ 
        marginLeft: isMobile ? 0 : 260,
        flex: 1, 
        display: 'flex', 
        flexDirection: 'column', 
        minWidth: 0,
        width: '100%',
        transition: 'margin-left 0.3s ease',
      }}>
        
        {/* Шапка */}
        <header style={{
          background: '#fff',
          borderBottom: '1px solid #e5e7eb',
          padding: '0 24px',
          height: 60,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          position: 'sticky',
          top: 0,
          zIndex: 40,
          boxShadow: '0 1px 4px rgba(0,0,0,0.04)',
          gap: 16,
        }}>
          {/* Кнопка бургер-меню для мобильных */}
          {isMobile && (
            <button
              onClick={toggleMobileMenu}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                padding: '8px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: 8,
                transition: 'background 0.2s',
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#f3f4f6'}
              onMouseLeave={e => e.currentTarget.style.background = 'none'}
              aria-label="Открыть меню"
            >
              <svg
                style={{ width: 20, height: 20 }}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M4 6h16M4 12h16M4 18h16"
                />
              </svg>
            </button>
          )}

          <div style={{ flex: 1 }}>
            <h2 style={{ 
              margin: 0, 
              fontSize: isMobile ? 14 : 15, 
              fontWeight: 600, 
              color: '#374151',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}>
              {getPageTitle()}
            </h2>
          </div>

          {/* Информация о времени (десктоп) */}
          {!isMobile && (
            <div style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'flex-end',
              marginRight: 16,
              borderRight: '1px solid #e5e7eb',
              paddingRight: 16,
            }}>
              <span style={{ fontSize: 12, color: '#6b7280' }}>
                {formattedDate}
              </span>
              <span style={{ fontSize: 13, fontWeight: 600, color: '#2563eb' }}>
                {formattedTime}
              </span>
            </div>
          )}

          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: 12,
            flexWrap: 'wrap',
            justifyContent: 'flex-end',
          }}>
            {/* Информация о пользователе */}
            <div style={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: 10,
              flexWrap: 'wrap',
              justifyContent: 'flex-end',
            }}>
              {!isMobile && (
                <>
                  <div style={{
                    width: 32,
                    height: 32,
                    borderRadius: '50%',
                    background: 'linear-gradient(135deg, #10b981, #059669)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: '#fff',
                    fontWeight: 600,
                    fontSize: 12,
                  }}>
                    {user?.full_name?.charAt(0) || '?'}
                  </div>
                  <span style={{ 
                    fontSize: 13, 
                    color: '#374151',
                    fontWeight: 500,
                    maxWidth: 150,
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                  }} title={user?.full_name}>
                    {user?.full_name || 'Пользователь'}
                  </span>
                </>
              )}
              
              <span style={{
                padding: '4px 10px',
                borderRadius: 20,
                fontSize: 11,
                fontWeight: 600,
                background: user?.role === 'admin' ? '#dbeafe' : '#d1fae5',
                color: user?.role === 'admin' ? '#1e40af' : '#065f46',
                whiteSpace: 'nowrap',
              }}>
                {user?.role === 'admin' ? 'Администратор' : 'Сотрудник'}
              </span>
              
              <button 
                onClick={handleLogout} 
                style={{
                  background: 'none',
                  border: 'none',
                  fontSize: 13,
                  color: '#ef4444',
                  cursor: 'pointer',
                  fontWeight: 500,
                  padding: '6px 12px',
                  borderRadius: 8,
                  transition: 'all 0.2s',
                  whiteSpace: 'nowrap',
                }}
                onMouseEnter={e => {
                  e.currentTarget.style.background = '#fef2f2';
                  e.currentTarget.style.transform = 'translateY(-1px)';
                }}
                onMouseLeave={e => {
                  e.currentTarget.style.background = 'none';
                  e.currentTarget.style.transform = 'translateY(0)';
                }}
                aria-label="Выйти из системы"
              >
                {isMobile ? '🚪' : 'Выйти'}
              </button>
            </div>
          </div>
        </header>

        {/* Основное содержимое страницы */}
        <main style={{ 
          flex: 1, 
          padding: isMobile ? 16 : 24,
          overflowY: 'auto',
          minHeight: 'calc(100vh - 60px)',
        }}>
          <Outlet />
        </main>

        {/* Футер (опционально) */}
        <footer style={{
          borderTop: '1px solid #e5e7eb',
          padding: '16px 24px',
          background: '#fff',
          fontSize: 12,
          color: '#9ca3af',
          textAlign: 'center',
        }}>
          <p style={{ margin: 0 }}>
            © {new Date().getFullYear()} WorkTime - Система учёта рабочего времени
            {!isMobile && ' · Все права защищены'}
          </p>
        </footer>

      </div>
    </div>
  );
};

export default DashboardLayout;
